re watery diarrhoea after two days\nof treatment and these symptoms persist along with cramping abdominal pain\nassociated with urgent call to stool, fever and nausea with intermittent vomiting.\nIn addition to cessation of amoxycillin, which one of the following is the most\nappropriate initial treatment?\n\n. Monitor progress without further antibiotics.\nCommence metronidazole.\n\n. Commence vancomycin.\n\nCommence chloramphenicol.\nCommence ciprafloxacin.\n\nMOQ2>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"f7e42f39ebcd858c2769840258acb09fdabaa8be","duplicate_group_id":"exact-f7e42f39ebcd","duplicate_sources":[{"record_id":"fc4ae1f37543ca218414","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":24,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_vers