INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('685fe9e75670eb96d906','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','33','Mixed/Unclassified','Australian Medical Council
Handbook of Multiple Choice Questions
Key Issue (‘Mastery’) Questions
Key Issue (‘Mastery’) questions were included in the fixed length AMC MCQ
examination, which continued until mid-2009.
Mastery questions were defined as key or critical issue questions regarded as critical to
the safety or clinical outcome or threat to life for the patient, or based upon important
common conditions; together with one of the following aspects.
¢ Related to life threatening illness
* Critical to safe practice (includes professionalism)
« Successful clinical outcome
¢ Important aspects of public health.
Mastery questions were individually identified to candidates throughout the
examination papers with an asterisk [*].
Example
MCQ 1.9 = ‘Mastery’ question - ACUTE BACK PAIN WITH POOR BLADDER AND
BOWEL CONTROL
A 38-year-old builder had acute back pain which subsided over 24 hours. He now
complains of increasing numbness and tingling in both legs and poor bladder and
bowel control. Which one of the following should be the first step in management?','{"A":"Physiotherapy.","B":"Strict bed rest with pelvic traction.","C":"Epidural local anaesthesia.","D":"Spinal manipulation.","E":"Magnetic resonance imaging (MRI).\n\nExample\nMCQ 1.10 - ‘Mastery’ question - GAS GANGRENE IN A 25-YEAR-OLD MAN\n\nA 25-year-old man is admitted to hospital severely ill 18 hours after a major crush injury\nto his leg from a fallen tree while camping. You have examined him and made a\nclinical diagnosis of ‘gas gangrene’. Which one of the following is the most important\nstep in treatment of his condition?\n\nAdequate polyvalent gas gangrene antitoxin.\n\nAdequate surgical removal of devitalised tissue.\n\n. Ahigh initial dose of parenteral antibiotic.\n\nA prolonged course of parenteral antibiotic treatment.\nHyperbaric oxygen treatment prior to operative treatment.\n\nCommentary MCQ 1.9\n\nThe symptoms described, with bilateral sensory symptoms and involvement of\nsphincter control, suggest acute compression of either the cauda equina or the lower\nend of the spinal cord. With the involvement of the bladder and bowel it is urgent to\nestablish the cause of this compression. For this reason, of the options listed, urgent\nmagnetic resonance imaging (MRI) would be the most appropriate (E is"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-197401807ab5","duplicate_sources":[{"record_id":"685fe9e75670eb96d906","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":33,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_