INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9cc2804c7505ab50878a','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','35','Mixed/Unclassified','Australian Medical Council
Handbook of Multiple Choice Questions
with known performance characteristics on the same scale, as the performance
ability of candidates is progressively mapped, and therefore a relationship can be
established. Questions presented to a candidate are selected at random according
to the examination blueprint requirements, but focus down with decreasing error on
the ability level of the candidate, from which a pass/fail decision can be made by
comparing the level achieved with the required score on the AMC scale over an
appropriate range of disciplines.
In practical terms, each candidate begins the examination by being presented with
a randomly selected group of questions chosen from the range of patient groups
and clinical task areas. The performance on these is used to calculate an initial ability
level. Further questions are then selected from around that ability level depending on
the responses made by the candidate. More difficult questions are selected when
a correct response is given, and less difficult questions are selected when a wrong
answer is given. Once a statistically valid and acceptable estimation of candidate
ability, with minimal change, has been achieved the established ability on the AMC
scale is attributed to the candidate.
‘Least likely’ questions
Most clinical problem-solving involves noting and following up clinical features which
support a diagnosis, but the absence of a feature in history or examination may
also be of great diagnostic value by facilitating elimination of alternative diagnostic
options. Diagnostic questioning is often alternated between those questions aimed
at confirming a diagnosis, and others aimed at eliminating less likely alternatives.
A small minority of questions may be of this ‘least likely’ or ‘least common'' type, to
test candidates’ ability to identify aspects of the clinical picture which enable one to
identify the least likely of the five alternative responses, and thus establish the first of
the differential diagnoses to be eliminated.
Another form of ‘least likely’ questions may focus on which one of five possible
investigations has least diagnostic utility, when several are available and appropriate
in assessment of the patient''s problem.
Ability to identify negative cues can thus be important in clinical reasoning skills
(identifying features that are not usual components of the constellation of features
typical of a condition).
When using this type of ‘least likely’ question, all the response subsets should, when
possible, be included in the stem (as in Examples MCQ 1.11 and 1.12 below, relating
to the diagnosis of abdominal pain). The answer should then be capable of being
deduced from the stem before reference to the responses (the ‘cover’ test).
Example
MCQ 1.11 = CLINICAL FEATURES OF ACUTE APPENDICITIS — 1
A 25-year-old woman presents with a 24-hour history of lower abdominal pain,
anorexia, nausea and vomiting, and has a fever of 40°C. Which one of these clinical
features is least consistent with a diagnosis of acute non-perforated appendicitis?','{"A":"Anorexia.","B":"Nausea.","C":"Vomiting.","D":"Lower abdominal pain.\nTemperature of 40°C.","E":"moO"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-327edb24ec8c","duplicate_sources":[{"record_id":"9cc2804c7505ab50878a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":35,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"9cc2804c7505ab50878a","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":35,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nHandbook of Multiple Choice Questions\nwith known performance characteristics on the same scale, as the performance\nability of candidates is progressively mapped, and therefore a relationship can be\nestablished. Questions presented to a candidate are selected at random according\nto the examination blueprint requirements, but focus down with decreasing error on\nthe ability level of the candidate, from which a pass/fail decision can be made by\ncomparing the level achieved with the required score on the AMC scale over an\nappropriate range of disciplines.\nIn practical terms, each candidate begins the examination by being presented with\na randomly selected group of questions chosen from the range of patient groups\nand clinical task areas. The performance on these 