‘cover’ test).\nExample\nMCQ 1.11 = CLINICAL FEATURES OF ACUTE APPENDICITIS — 1\nA 25-year-old woman presents with a 24-hour history of lower abdominal pain,\nanorexia, nausea and vomiting, and has a fever of 40°C. Which one of these clinical\nfeatures is least consistent with a diagnosis of acute non-perforated appendicitis?","options":{"A":"Anorexia.","B":"Nausea.","C":"Vomiting.","D":"Lower abdominal pain.\nTemperature of 40°C.","E":"moO"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"327edb24ec8cc1f8001d5ea410b6491f289396e4","duplicate_group_id":"exact-327edb24ec8c","duplicate_sources":[{"record_id":"9cc2804c7505ab50878a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":35,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=