INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a3183eca1f28a8652f75','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','36','Mixed/Unclassified','Handbook of Multiple Choice Questions
Example
MCQ 1.12 — CLINICAL FEATURES OF ACUTE APPENDICITIS — 2
A 25-year-old woman passed a loose bowel action before going to bed. She awoke
the next morning feeling unwell and nauseated. She vomited repeatedly and passed
another loose motion. Several hours later she developed lower abdominal pain,
which progressively worsened, and she presented to hospital. On examination her
temperature was 37.5°C. The white cell count was normal. Which one of these clinical
features is least consistent with a diagnosis of acute appendicitis?','{"A":"Temperature of 37.5°C.","B":"Worsening lower abdominal pain.","C":"Repeated vomiting preceding pain.","D":"Prodromal bowel upset.","E":"Normal white cell count.\nCommentary —- MCQ 1.11 and MCQ 1.12\nThe correct responses are E (Temperature of 40°C) and C (Repeated vomiting\npreceding pain) respectively in Examples 1.11 and 1.12.\nIn Example MCQ 1.11,the patient''s history is of only 24 hours duration and a high\nfever of 40°C within the first 24 hours would be unusual in non-perforated acute\nappendicitis.\nThe typical march of symptoms (J.B Murphy'') in acute appendicitis is often a\nprodromal mild bowel upset; then the development of abdominal pain, which\nprogressively worsens; subsequent anorexia, nausea and vomiting; then a moderate\nfever with signs of focal peritonitis over the inflamed appendix.\nIn Example 1.12, repeated vomiting prior to the development of abdominal pain is\ndistinctly unusual in appendicitis and would suggest the possibility of another diagnosis"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[36],"source_qid":null,"duplicate_group_id":"exact-2bfc2fcd11d5","duplicate_sources":[{"record_id":"a3183eca1f28a8652f75","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":36,"source_qid":null}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"a3183eca1f28a8652f75","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":36,"supporting_pages":[36],"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Handbook of Multiple Choice Questions\nExample\nMCQ 1.12 — CLINICAL FEATURES OF ACUTE APPENDICITIS — 2\nA 25-year-old woman passed a loose bowel action before going to bed. She awoke\nthe next morning feeling unwell and nauseated. She vomited repeatedly and passed\nanother loose motion. Several hours later she developed lower abdominal pain,\nwhich progressively worsened, and she presented to hospital. On examination her\ntemperature was 37.5°C. The white cell count was normal. Which one of these clinical\nfeatures is least consistent with a diagnosis of acute appendicitis?","options":{"A":"Temperature of 37.5°C.","B":"Worsening lower abdominal pain.","C":"Repeated vomiting preceding pain.","D":"Prodromal bowel upset.","E":"Normal white cell count.\nCommentary —- MCQ 1.11 and MCQ 1.12\nThe correct responses are E (Temperature of 40°C) and C (Repeated vomiting\npreceding pain) respectively in Examples 1.11 and 1.12.\nIn Example MCQ 1.11,the patient''s history is of only 24 hours duration and a high\nfever of 40°C within the first 24 hours would be unusual in non-perforated acute\nappendicitis.\nThe typical march of symptoms (J.B Murphy'') in acute appendicitis is often a\nprodromal mild bowel upset; then the development of abdominal pain, which\nprogressively worsens; subsequent anorexia, nausea and vomiting; then a moderate\nfever with signs of focal peritonitis over the inflamed appendix.\nIn Example 1.12, repeated vomiting prior to the development of abdominal pain is\ndistinctly unusual in appendicitis and would suggest the possibility of another diagnosis"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"2bfc2fcd11d554d75161f869a184d75f81c8003c","duplicate_group_id":"exact-2bfc2fcd11d5","duplicate_sources":[{"record_id":"a3183eca1f28a8652f75","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":36,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
