INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('36345509347cf7944438','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','43','Mixed/Unclassified','Australian Medical Council
Handbook of Multiple Choice Questions
Example
MCQ 1.14 - HYPERTENSION IN A 16-YEAR-OLD BOY
A 16-year-old boy is seen for routine medical examination. On examination his height
is 170cm (25th percentile), weight 88kg (95th percentile). His BP is 160/70mmHg. His
heart rate is 75/min. Which one of the following is the most appropriate next step in
the management of this boy''s blood pressure?','{"A":"Measure serum creatinine.","B":"Monitor 24-hour blood pressure.","C":"Obtain a urinalysis.","D":"Check blood pressure cuff size.","E":"Obtain an electrocardiogram.\n\nExample\nMCQ 1.15 — CONFUSION AFTER A HEAD INJURY\n\nA 65-year-old patient is confused and delirious after a head injury, and plasma\nelectrolytes show a sodium level of 120mmol/L. This plasma sodium concentration of\n120mmol/L indicates which one of the following conditions?\n\nA. Decreased extracellular osmolality.\n\nB. Decreased total body water.\n\nC. Decreased total body sodium.\n\nD. Excess sodium loss from the extracellular fluid space.\nE. Deficiency of antidiuretic hormone (ADH).\n\nExample\nMCQ 1.16 — PUBERTY SIGNS IN FEMALES\n\nPubertal changes in females include a growth spurt, development of pubic and\naxillary hair, breast bud enlargement, and onset of menstruation. Which one of the\nfollowing signs of puberty should be expected during observation in a 9-year-old\ngirl?\n\nA. A growth spurt as reflected by an increase in height.\n\nB. The development of pubic hair.\n\nC. The development of axillary hair.\n\nD. Enlargement of the breast buds.\n\nE. The onset of menstruation.\n\nExample\nMCQ 1.17 — PROPERTIES OF MAMMOGRAPHY\n\nA 40-year-old woman seeks advice about the benefits of mammography as a\nscreening test and in the diagnosis of breast lumps. She wishes to know whether it\nis equally useful at all ages, and how it compares with self-examination and other\nimaging modalities in causing discomfort and being able to differentiate cancer\nfrom cysts and other pathologies. In counselling her, you should be aware that\nmammography, in regard to these aspects of concern, has which one of the following\nproperties?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-84f8848444f5","duplicate_sources":[{"record_id":"36345509347cf7944438","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":43,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"36345509347cf7944438","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":43,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nHandbook of Multiple Choice Questions\nExample\nMCQ 1.14 - HYPERTENSION IN A 16-YEAR-OLD BOY\nA 16-year-old boy is seen for routine medical examination. On examination his height\nis 170cm (25th percentile), weight 88kg (95th percentile). His BP is 160/70mmHg. His\nheart rate is 75/min. Which one of the following is the most appropriate next step in\nthe management of this boy''s blood pressure?","options":{"A":"Measure serum creatinine.","B":"Monitor 24-hour blood pressure.","C":"Obtain a urinalysis.","D":"Check blood pressure cuff size.","E":"Obtain an electrocardiogram.\n\nExample\nMCQ 1.15 — CONFUSION AFTER A HEAD INJURY\n\nA 65-year-old patient is confused and delirious after a head injury, and plasma\nelectrolytes show a sodium level of 120mmol/L. This plasma sodium concentration of\n120mmol/L indicates which one of the following conditions?\n\nA. Decreased extracellular osmolality.\n\nB. Decreased total body water.\n\nC. Decreased total body sodium.\n\nD. Excess sodium loss from the extracellular fluid space.\nE. Deficiency of antidiuretic hormone (ADH).\n\nExample\nMCQ 1.16 — PUBERTY SIGNS IN FEMALES\n\nPubertal changes in females include a growth spurt, development of pubic and\naxillary hair, breast bud enlargement, and onset of menstruation. Which one of the\nfollowing signs of puberty should be expected during observation in a 9-year-old\ngirl?\n\nA. A growth spurt as reflected by an increase in height.\n\nB. The development of pubic hair.\n\nC. The development of axillary hair.\n\nD. Enlargement of the breast buds.\n\nE. The onset of menstruation.\n\nExample\nMCQ 1.17 — PROPERTIES OF MAMMOGRAPHY\n\nA 40-year-old woman seeks advice about the benefits of mammography as a\nscreening test and in the diagnosis of breast lumps. She wishes to know whether it\nis equally useful at all ages, and how it compares with self-examination and other\nimaging modalities in causing discomfort and being able to differentiate cancer\nfrom cysts and other pathologies. In counselling her, you should be aware that\nmammography, in regard to these aspects of concern, has which one of the following\nproperties?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","hypertension","management"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"84f8848444f5ce8d4ea3916ddab031be87d5b0ce","duplicate_group_id":"exact-84f8848444f5","duplicate_sources":[{"record_id":"36345509347cf7944438","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":43,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
