electrolytes show a sodium level of 120mmol/L. This plasma sodium concentration of
120mmol/L indicates which one of the following conditions?','{"A":"Decreased extracellular osmolality.","B":"Decreased total body water.","C":"Decreased total body sodium.","D":"Excess sodium loss from the extracellular fluid space.","E":"Deficiency of antidiuretic hormone (ADH).\n\nExample\nMCQ 1.16 — PUBERTY SIGNS IN FEMALES\n\nPubertal changes in females include a growth spurt, development of pubic and\naxillary hair, breast bud enlargement, and onset of menstruation. Which one of the\nfollowing signs of puberty should be expected during observation in a 9-year-old\ngirl?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[43],"source_qid":null,"duplicate_group_id":"exact-491e271a26a8","duplicate_sources":[{"record_id":"a6dc5fcfddfbee982cd0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":43,"source_qid":null}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_multi_question_group","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"a6dc5fcfddfbee982cd0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":43,"supporting_pages":[43],"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 65-year-old patient is confused and delirious after a head injury, and plasma\nelectrolytes show a sodium level of 120mmol/L. This plasma sodium concentration of\n120mmol/L indicates which one of the following conditions?","options":{"A":"Decreased extracellular osmolality.","B":"Decreased total body water.","C":"Decreased total body sodium.","D":"Excess sodium loss from the extracellular fluid space.","E":"Deficiency of antidiuretic hormone (ADH).\n\nExample\nMCQ 1.16 — PUBERTY SIGNS IN FEMALES\n\nPubertal changes in females include a growth spurt, development of pubic and\naxillary hair, breast bud enlargement, and onset of menstruation. Which one of the\nfollowing signs of puberty should be expected during observation in a 9-year-old\ngirl?"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_multi_question_group","text_method":"tesseract","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"491e271a26a8db526599d4110c6320b17ebef71d","duplicate_group_id":"exact-491e271a26a8","duplicate_sources":[{"record_id":"a6dc5fcfddfbee982cd0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":43,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.impor