INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('50a57406e4528a9af5d2','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','64','Mixed/Unclassified','Section 2 —Trial Examination
MCQ 2.007
A 30-year-old woman delivered spontaneously 20 minutes ago after a 16-ho
labour. She was given ten units of oxytocin (Syntocinon®) intravenously immediatelj
after the birth and was delivered of her placenta three minutes later. She has since
lost 750mL of blood vaginally. After ‘rubbing up’ the uterine fundus manually, which
one of the following is the most appropriate next step in managemente2
A. Inspect the placenta.
B. Inspect the vagina and cervix for a laceration.
C. Empty the bladder.
D. Cross-match blood.
E. Give ergometrine intravenously.
MCQ 2.008
A 52-year-old man presents at the clinic, seeking advice on screening for carcinoma
of the large bowel. He has no gastrointestinal symptoms. His younger brother has jusi
developed a colonic cancer at the age of 50. There is no other family history. Which
one of the following is the most appropriate advice to give to him about curre
and future management?
A. No screening procedure is required at this time.
B. He should undergo faecal occult blood testing (FOBT) now.
C. Colonoscopy should be performed now and, if clear, no further screening is
required.
D. Colonoscopy should be performed now and at five-yearly intervals thereafter.
E. Colonoscopy should be performed now and yearly thereafter.
MCQ 2.009
A 55-year-old dye factory worker presented with painless haematuria and a
computed tomograph with contrast showed a filling defect arising from the rend
pelvis suggestive of a urothelial tumour. Which one of the following is the most
appropriate treatment?','{"A":"Nephrectomy.","B":"Open fulguration.","C":"Cytoxic drugs.","D":"Nephroureterectomy.","E":"External irradiation therapy.\n48"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[64],"source_qid":"2.007","duplicate_group_id":"exact-f7bfcb60eb44","duplicate_sources":[{"record_id":"50a57406e4528a9af5d2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":64,"source_qid":"2.007"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"50a57406e4528a9af5d2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":64,"supporting_pages":[64],"source_qid":"2.007","domain_hint":"Mixed/Unclassified","stem":"Section 2 —Trial Examination\nMCQ 2.007\nA 30-year-old woman delivered spontaneously 20 minutes ago after a 16-ho\nlabour. She was given ten units of oxytocin (Syntocinon®) intravenously immediatelj\nafter the birth and was delivered of her placenta three minutes later. She has since\nlost 750mL of blood vaginally. After ‘rubbing up’ the uterine fundus manually, which\none of the following is the most appropriate next step in managemente2\nA. Inspect the placenta.\nB. Inspect the vagina and cervix for a laceration.\nC. Empty the bladder.\nD. Cross-match blood.\nE. Give ergometrine intravenously.\nMCQ 2.008\nA 52-year-old man presents at the clinic, seeking advice on screening for carcinoma\nof the large bowel. He has no gastrointestinal symptoms. H