INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('473fd935ad89d0063eb2','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','65','Mixed/Unclassified','A 35-year-old business executive, who is otherwise well, presents with a sensation
of a lump in the lower pharynx for six months. There are no abnormal findings on
examination of neck or pharynx. Which one of the following is the most likely cause
of his symptoms?','{"A":"Pharyngeal pouch.","B":"Chronic tonsillitis.","C":"Psychogenic factors.","D":"Oesophageal hiatus hernia.","E":"Lingual thyroid.\n\nMCQ 2.011\n\nFollowing a delivery complicated by shoulder dystocia, a newborn baby is found to\nhave an asymmetric Moro reflex. The poorly responsive arm hangs limp in adduction,\nrotated internally at the shoulder, extended and pronated at the elbow, and flexed\nat the wrist. Which one of the following pairs of nerve roots is most likely to have\nbeen affected?\n\nA. C3.and C4.\nB. C5 and Cé.\nC. C8 and Tl.\nD. T2 and 73.\nE. T4and 15.\n\nMCQ 2.012\n\nA 65-year-old woman presents with progressively worsening deafness over the past\nsix months. She finds hearing particularly difficult when in a noisy environment. She\nthinks the right ear is more affected than the left. Clinical hearing tests are done\nwith results as follows.\n\nHearing of whispered voice appears diminished on both sides. A Rinne test shows air\nconduction (AC) is better than bone conduction (BC) in each ear. On performing\nthe Weber test, she says the sound is louder in the left ear.\n\nWhich one of the following is the"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.010","duplicate_group_id":"exact-002fb600e920","duplicate_sources":[{"record_id":"473fd935ad89d0063eb2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":65,"source_qid":"2.010"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"473fd935ad89d0063eb2","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":65,"source_qid":"2.010","domain_hint":"Mixed/Unclassified","stem":"A 35-year-old business executive, who is otherwise well, presents with a sensation\nof a lump in the lower pharynx for six months. There are no abnormal findings on\nexamination of neck or pharynx. Which one of the following is the most likely cause\nof his symptoms?","options":{"A":"Pharyngeal pouch.","B":"Chronic tonsillitis.","C":"Psychogenic factors.","D":"Oesophageal hiatus hernia.","E":"Lingual thyroid.\n\nMCQ 2.011\n\nFollowing a delivery complicated by shoulder dystocia, a newborn baby is found to\nhave an asymmetric Moro reflex. The poorly responsive arm hangs limp in adduction,\nrotated internally at the shoulder, extended and pronated at the elbow, and flexed\nat the wrist. Which one of the following pairs of nerve roots is most likely to have\nbeen affected?\n\nA. C3.and C4.\nB. C5 and Cé.\nC. C8 and Tl.\nD. T2 and 73.\nE. T4and 15.\n\nMCQ 2.012\n\nA 65-year-old woman presents with progressively worsening deafness over the past\nsix months. She finds hearing particularly difficult when in a noisy environment. She\nthinks the right ear is more affected than the left. Clinical hearing tests are done\nwith results as follows.\n\nHearing of whispered voice appears diminished on both sides. A Rinne test shows air\nconduction (AC) is better than bone conduction (BC) in each ear. On performing\nthe Weber test, she says the sound is louder in the left ear.\n\nWhich one of the following is the"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"002fb600e92096e7896f069a0ca7d288e3c0a6cd","duplicate_group_id":"exact-002fb600e920","duplicate_sources":[{"record_id":"473fd935ad89d0063eb2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":65,"source_qid":"2.010"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
