INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('93842f92c43b2c06c737','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','67','Mixed/Unclassified','foal
Australian Medical Council
Section 2 — Trial Examination
MCQ 2.016
Which one of the following groups has the highest risk of developing an iron
deficiency?','{"A":"Breast-fed babies.","B":"Toddlers.","C":"Vegetarians.","D":"Adult indigenous males.","E":"Postmenopausal females.\n\nMCQ 2.017\n\nA 44-year-old man presents with a two-day history of pain in the left side of the\nscrotum. He has no other symptoms and is normally in good health. On examination\nhe has a temperature of 38.6°C. The left hemiscrotum is reddened and tender\nto touch. The testis and cord appear enlarged and thickened. Which one of the\nfollowing is the most likely diagnosis?\n\nA. Obstructed inguinal hernia.\nB. Varicocele.\n\nC. Torsion of the testis.\n\nD. Infected hydrocele.\n\nE. Epididymo-orchitis.\n\nMCQ 2.018\n\nA 25-year-old nulliparous woman presents with a two-week history of a painless\nswelling in her right breast. On examination there is a discrete firm mobile mass in the\nfight upper quadrant, 2cm in diameter. Which one of the following is the most likely\ndiagnosis?\n\nCarcinoma of the breast.\n\nFibroadenoma.\n\n. Intraduct papilloma.\n\n. A prominent area of fibroadenosis.\n\nAn area of traumatic fat necrosis.\n\nMOQO2>\n\nMCQ 2.019\n\nYou have been asked to review a 54-year-old woman with a 30-year history of\nparanoid schizophrenia, with multiple hospitalisations usually preceded by cessation\nof antipsychotic medication. Her mental state reveals that she is suspicious,\nguarded and grandiose. She believes that she has unique healing powers and can\ncommunicate with angels. She is insistent that her experiences are real, and that\nshe has been falsely labelled mentally ill and does not require any medication. Her\ninsistence that she is well and not in need of treatment is an example of which one\nof the following?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.016","duplicate_group_id":"exact-c96204136532","duplicate_sources":[{"record_id":"93842f92c43b2c06c737","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":67,"source_qid":"2.016"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"93842f92c43b2c06c737","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":67,"source_qid":"2.016","domain_hint":"Mixed/Unclassified","stem":"foal\nAustralian Medical Council\nSection 2 — Trial Examination\nMCQ 2.016\nWhich one of the following groups has the highest risk of developing an iron\ndeficiency?","options":{"A":"Breast-fed babies.","B":"Toddlers.","C":"Vegetarians.","D":"Adult indigenous males.","E":"Postmenopausal females.\n\nMCQ 2.017\n\nA 44-year-old man presents with a two-day history of pain in the left side of the\nscrotum. He has no other symptoms and is normally in good health. On examination\nhe has a temperature of 38.6°C. The left hemiscrotum is reddened and tender\nto touch. The testis and cord appear enlarged and thickened. Which one of the\nfollowing is the most likely diagnosis?\n\nA. Obstructed inguinal hernia.\nB. Varicocele.\n\nC. Torsion of the testis.\n\nD. Infected hydrocele.\n\nE. Epididymo-orchitis.\n\nMCQ 2.018\n\nA 25-year-old nulliparous woman presents with a two-week history of a painless\nswelling in her right breast. On examination there is a discrete firm mobile mass in the\nfight upper quadrant, 2cm in diameter. Which one of the following is the most likely\ndiagnosis?\n\nCarcinoma of the breast.\n\nFibroadenoma.\n\n. Intraduct papilloma.\n\n. A prominent area of fibroadenosis.\n\nAn area of traumatic fat necrosis.\n\nMOQO2>\n\nMCQ 2.019\n\nYou have been asked to review a 54-year-old woman with a 30-year history of\nparanoid schizophrenia, with multiple hospitalisations usually preceded by cessation\nof antipsychotic medication. Her mental state reveals that she is suspicious,\nguarded and grandiose. She believes that she has unique healing powers and can\ncommunicate with angels. She is insistent that her experiences are real, and that\nshe has been falsely labelled mentally ill and does not require any medication. Her\ninsistence that she is well and not in need of treatment is an example of which one\nof the following?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c962041365321f690f8c7e8c59f2da99fef9c2f2","duplicate_group_id":"exact-c96204136532","duplicate_sources":[{"record_id":"93842f92c43b2c06c737","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":67,"source_qid":"2.016"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,r