INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7e833506074a0ccb1ff1','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','79','Mixed/Unclassified','A 21-year-old primigravid woman, at 39 weeks of gestation by uncertain dates,
attends the antenatal clinic at the local hospital for her first antenatal visit. She
has just arrived from overseas, having had no antenatal care in her country of
origin. Her BP is 120/80mmtg. The fundal height measures 30cm above the pubic
symphysis. Fetal heart tones are evident at 144/min. Pelvic examination reveals the
cervix is long and closed, and the baby is presenting cephalically. Which one of the
following is the most appropriate next step in management?','{"A":"Fetal kick chart.","B":"Cardiotocograph (CTG).","C":"Amniocentesis.","D":"Ultrasound examination.","E":"Umbilical artery waveforms (Doppler).\n\nMCQ 2.054\n\nA 24-year-old woman presents with bruising and excessive cyclical menstrual loss\nwhich commenced four months ago. A blood count shows that she has a normal\nblood film apart from a platelet count of 20x10°/L (150-400). Physical examination is\nunremarkable apart from an enlarged spleen which is palpable 3cm below the left\ncostal margin. Which one of the following is the most likely diagnosis?\n\nA. Iron deficiency.\n\nB. Immune thrombocytopenic purpura (ITP).\nC. Chronic lymphocytic leukaemia.\n\nD. Systemic lupus erythematosus (SLE).\n\nE. Portal hypertension.\n\nMCQ 2.055\n\nA 35-year-old dressmaker sustained a puncture wound, from a sewing needle, in\nthe proximal interphalangeal flexor crease of her left index finger. Subsequently the\nfinger became swollen along its entire length. Passive extension of the digit elicited\nsevere pain. Which one of the following is the most likely diagnosis?\n\n. Abscess of the midpalmar space.\nSuperficial cellulitis.\n. Osteomyelitis of the proximal phalanx.\n. ‘Collar stud’ abscess.\nFlexor tenosynovitis.\n\nLER AS) @) hod 3\n\nAustralian Medical Council\nSection 2 - Trial Examination"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.053","duplicate_group_id":"exact-559a1fe2c9cd","duplicate_sources":[{"record_id":"7e833506074a0ccb1ff1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":79,"source_qid":"2.053"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"as