INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2bf3d3d8bef0c299590e','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','80','Mixed/Unclassified','Ausiralian Medical Council
Section 2 - Trial Examination
MCQ 2.056
A 55-year-old woman presents with increasing dyspnoea over a three-mon
period. Examination findings include a raised jugular venous pressure (JVP) withou
displacement of the apex beat. Which one of the following is the least likely i
cause this combination of physical findings?
Mitral regurgitation.
Cor pulmonale.
. Myocardial infarction.
. Mitral stenosis.
Constrictive pericarditis.
MFO © Paps
MCQ 2.057
A 64-year-old man presents with a two-month history of a cramping pain in
the right buttock. This pain only appears when he is walking and comes on afte
several minutes. The pain radiates from the buttock down the right thigh and goes
away when he stops walking to rest. Which one of the following is the most likely
explanation for his symptoms?','{"A":"Stenosis of his right common iliac artery.","B":"Spinal canal stenosis.","C":"LA4/L5 disc focal prolapse.","D":"Stenosis of his right superficial femoral artery.","E":"Osteoarthritis of his right hip.\n\nMCQ 2.058\n\nA 65-year-old patient presents with a history of severe abdominal pain, shock,\nmoderate abdominal rigidity and intense lower back pain. This presentation is most\ncharacteristic of which one of the following conditions?\n\n. Acute retrocaecal appendicitis.\nLeaking aortic aneurysm.\n\n. Renal colic.\n\n. Acute cholecystitis.\nCollapse of L1 vertebral body.\n\nMm 0 QOwms>:\n\nMCQ 2.059\n\nA 70-year-old woman presents with a blood-stained vaginal discharge. Both the\nectocervix and the vagina look atrophic on speculum examination. Cervical\ncytology shows no evidence of malignant cells, although no endocervical cells were\nseen. Which one of the following is the most appropriate next step in managment?\n\n. Vaginal swab for microscopy and culture.\nColposcopy.\n\n. Ultrasound assessment of endometrial thickness.\nHysteroscopy and dilatation and curettage (D&C).\nLaparoscopy. Hy\n\nMOORP>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.056","duplicate_group_id":"exact-5e950b3baf4d","duplicate_sources":[{"record_id":"2bf3d3d8bef0c299590e","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":80,"source_qid":"2.056"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"2bf3d3d8bef0c299590e","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path"