The child appears to turn in response to sound. He was born at 36 weeks gestation,
weighing 2600g. He passed his neonatal hearing screen. Which one of the following
is the most appropriate next step in management?','{"A":"Arrange maternal and child health hearing screen.","B":"Arrange an audiological assessment.","C":"Reassure that this is a normal variant in development.","D":"Repeat developmental assessment at 18 months.","E":"Check for dysmorphic features.\n\nMCQ 2.062\n\nWhich one of the following findings in a woman in labour, where the cervix is 7¢m\ndilated, would be most consistent with obstructed labour and the need for delivery"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[81],"source_qid":"2.060","duplicate_group_id":"exact-b880cf96d632","duplicate_sources":[{"record_id":"0b14123825d7812b15f0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":81,"source_qid":"2.060"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_multi_question_group","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"0b14123825d7812b15f0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":81,"supporting_pages":[81],"source_qid":"2.060","domain_hint":"Mixed/Unclassified","stem":"A 15-month-old child is noticed by his parents not to be babbling and has no words.\nThe child appears to turn in response to sound. He was born at 36 weeks gestation,\nweighing 2600g. He passed his neonatal hearing screen. Which one of the following\nis the most appropriate next step in management?","options":{"A":"Arrange maternal and child health hearing screen.","B":"Arrange an audiological assessment.","C":"Reassure that this is a normal variant in development.","D":"Repeat developmental assessment at 18 months.","E":"Check for dysmorphic features.\n\nMCQ 2.062\n\nWhich one of the following findings in a woman in labour, where the cervix is 7¢m\ndilated, would be most consistent with obstructed labour and the need for delivery"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_multi_question_group","text_method":"tesseract","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"b880cf96d632e23c30f095ff907ac28eb935ad9a","duplicate_group_id":"exact-b880cf96d632","duplicate_sources":[{"record_id":"0b14123825d7812b15f0","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":81,"source_qid":"2.060"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
