INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('290431dfb51edacdc608','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','81','Mixed/Unclassified','A farmer has come to see you about advice on hydatid disease. He has been told
that the reason he developed a hydatid (Echinococcus granulosus) cyst in his liver
was that his farm was contaminated and he needs to ‘get rid of the infection.’
Which one of the following is the best way to eradicate the Echinococcus from his
property?
. Vaccinate his sheep.
Vaccinate his dogs.
. Deworm his sheep.
. Deworm his dogs.
Replace the lucerne grass in the paddocks with alfalfa.
mS @ Ser
MCQ 2.061
A 15-month-old child is noticed by his parents not to be babbling and has no words.
The child appears to turn in response to sound. He was born at 36 weeks gestation,
weighing 2600g. He passed his neonatal hearing screen. Which one of the following
is the most appropriate next step in management?','{"A":"Arrange maternal and child health hearing screen.","B":"Arrange an audiological assessment.","C":"Reassure that this is a normal variant in development.","D":"Repeat developmental assessment at 18 months.","E":"Check for dysmorphic features.\n\nMCQ 2.062\n\nWhich one of the following findings in a woman in labour, where the cervix is 7¢m\ndilated, would be most consistent with obstructed labour and the need for delivery\nby Caesarean section?\n\nA. A brow presentation in a nulliparous woman.\n\nB. Caput and moulding of the fetal head.\n\nC. Early fetal heart decelerations from 160 to 120/min on the cardiotocograph\n(CTG).\n\nD. The fetal head is still just above the ischial spines.\n\nE. A maternal fever of 37.8°C.\n\nMCQ 2.063\n\nA 38-year-old woman undergoes cervical percutaneous sympathetic nerve block\nfor relief of hyperhidrosis. Two hours after the procedure she becomes distressed and\nis observed to have laboured gasping respirations, a pulse rate of 110/min and a\nBP of 105/70mmHg. Which one of the following is the most likely explanation for her\nsymptoms?\n\nHaemothorax.\n\nPneumothorax.\n\n. Diaphragmatic paralysis.\n\n. Anaphylactic reaction.\n\nSpinal shock.\n\nMOOP>\n\nid\n\nAustralian Medical Council\nSection 2 — Trial Examination"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.060","duplicate_group_id":"exact-0c7add9e3d6d","duplicate_sources":[{"record_id":"290431dfb51edacdc608","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":81,"source_qid":"2.060"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"290431dfb51edacdc608","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":81,"source_qid":"2.060","domain_hint":"Mixed/Unclassified","stem":"A farmer has come to see you about advice on hydatid disease. He has been told\nthat the reason he developed a hydatid (Echinococcus granulosus) cyst in his liver\nwas that his farm was contaminated and he needs to ‘get rid of the infection.’\nWhich one of the following is the best way to eradicate the Echinococcus from his\nproperty?\n. Vaccinate his sheep.\nVaccinate his dogs.\n. Deworm his sheep.\n. Deworm his dogs.\nReplace the lucerne grass in the paddocks with alfalfa.\nmS @ Ser\nMCQ 2.061\nA 15-month-old child is noticed by his parents not to be babbling and has no words.\nThe child appears to turn in response to sound. He was born at 36 weeks gestation,\nweighing 2600g. He passed his neonatal hearing screen. Which one of the following\nis the most appropriate next step in management?","options":{"A":"Arrange maternal and child health hearing screen.","B":"Arrange an audiological assessment.","C":"Reassure that this is a normal variant in development.","D":"Repeat developmental assessment at 18 months.","E":"Check for dysmorphic features.\n\nMCQ 2.062\n\nWhich one of the following findings in a woman in labour, where the cervix is 7¢m\ndilated, would be most consistent with obstructed labour and the need for delivery\nby Caesarean section?\n\nA. A brow presentation in a nulliparous woman.\n\nB. Caput and moulding of the fetal head.\n\nC. Early fetal heart decelerations from 160 to 120/min on the cardiotocograph\n(CTG).\n\nD. The fetal head is still just above the ischial spines.\n\nE. A maternal fever of 37.8°C.\n\nMCQ 2.063\n\nA 38-year-old woman undergoes cervical percutaneous sympathetic nerve block\nfor relief of hyperhidrosis. Two hours after the procedure she becomes distressed and\nis observed to have laboured gasping respirations, a pulse rate of 110/min and a\nBP of 105/70mmHg. Which one of the following is the most likely explanation for her\nsymptoms?\n\nHaemothorax.\n\nPneumothorax.\n\n. Diaphragmatic paralysis.\n\n. Anaphylactic reaction.\n\nSpinal shock.\n\nMOOP>\n\nid\n\nAustralian Medical Council\nSection 2 — Trial Examination"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen","vaccin"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0c7add9e3d6de324fa5563c4baeb82aef3b0bbae","duplicate_group_id":"exact-0c7add9e3d6d","duplicate_sources":[{"record_id":"290431dfb51edacdc608","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":81,"source_qid":"2.060"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_versio