INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('69a17ee73ea6c26d7c67','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','83','Mixed/Unclassified','Australian Medical Council
Section 2 — Trial Examination
MCQ 2.067
A 2-year-old child is brought in with persistent daytime and night-time cough over
many months. His weight is on the 10th percentile and height on the 25th percentile.
On examination of his chest there is a generalised wheeze and coarse crepitations.
His previous weight percentiles were 90th at birth, and 40th at one year of age. He is
developmentally normal. Which one of the following is the most appropriate course
of action?
. Prescribe a course of oral amoxycillin.
Commence chest physiotherapy.
. Order antigliadin antibodies.
. Order a sweat electrolyte test.
Prescribe a course of inhaled corticosteroids.
ful (Sf ©) G2 a>
MCQ 2.068
A 68-year-old man with widely disseminated small cell carcinoma which originated
in the left lung is in considerable pain. He and his family have expressed their wish
for him to die peacefully at home. You suggest opiates for adequate pain relief.
Which one of the following side-effects is most likely to be a significant problem in his
management?
. Respiratory depression.
Drowsiness.
. Nausea.
. Constipation.
Hypotension.
TOG Sao
MCQ 2.069
An 8-year-old girl presents with recurrent headaches for the past three months. These
have been occurring every three to four weeks, are described as throbbing, felt
across the forehead and are associated with nausea, vomiting, photophobia and
visual disturbance with spots in the visual fields. She has to lie down and eventually
falls asleep, waking a couple of hours later back to normal. Physical neurological
examination is normal. Which one of the following additional features in the history
would be most helpful in confirming diagnosis?','{"A":"past history of prematurity (31 weeks).","B":"family history of migraine.","C":"A past history of viral meningitis.","D":"history of a concussion injury at three years of age.\nEvidence that she has been bullied at school.","E":"MOQ >"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[83],"source_qid":"2.067","duplicate_group_id":"exact-f8c07e9222d1","duplicate_sources":[{"record_id":"69a17ee73ea6c26d7c67","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":83,"source_qid":"2.067"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"69a17ee73ea6c26d7c67","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":83,"supporting_pages":[83],"source_qid":"2.067","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 2 — Trial Examination\nMCQ 2.067\nA 2-year-old child is brought in with persistent daytime and night-time cough over\nmany months. His weight is on the 10th percentile and height on the 25th percentile.\nOn examination of his chest there is a generalised wheeze and coarse crepitations.\nHis previous weight percentiles were 90th at birth, and 40th at one year of age. He is\ndevelopmentally normal. Which one of the following is the most appropriate course\nof action?\n. Prescribe a course of oral amoxycillin.\nCommence chest physiotherapy.\n. Order antigliadin antibodies.\n. Order a sweat electrolyte test.\nPrescribe a c