INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fedf00d732da81919131','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','92','Mixed/Unclassified','Australian Medical Council
Section 2 - Trial Examination
MCQ 2.091
Over the course of a month, a 75-year-old man has two episodes of blurring of vision
affecting the right eye. Each lasted around five minutes with gradual complete
resolution. Ocular examination on Presentation to his general practitioner shows
normal eye movements and pupil reactions. Which one of the following is the most
appropriate next step in investigation?
. Ocular tonometry.
Carotid duplex Doppler studies.
. Cerebral computed tomography (CT).
. 24-hour BP monitoring.
Temporal artery biopsy.
——o————————
MCQ 2.092
MESZ@ gr: >
A 35-year-old mother of an 8-year-old child is considering a second pregnancy.
Her previous pregnancy was complicated by puerperal psychosis, for which she
had electroconvulsive therapy (ECT), and from which she made a prompt recovery
and has remained well since. Her physical health is excellent and she has a happy
marriage. Patient records indicate she is a very good mother. Which one of the
following is the most appropriate advice?','{"A":"In view of her age and previous problem, further pregnancies are out of the\nquestion.","B":"Start another pregnancy and see how she feels about it. If she has misgivings,\nthen have the pregnancy terminated.","C":"In view of her good outcome, there is minimal tisk of further recurrence.","D":"If she gets pregnant, then she should take prophylactic antipsychotics\nthroughout the pregnancy.","E":"There is a 15-20% chance of recurrence of psychosis postpartum.\n\nOO\n\nMCQ 2.093\n\nA 65-year-old man attends his local\ndoctor for a repeat prescription for\nan antihypertensive medication. The\ndoctor notices that the patient''s left\npupil is smaller than the right and is\nassociated with a drooping of the eyelid\nas illustrated. The patient comments\nthat he has noticed recently that even\nwhen he is hot, there is no sweating\non the left side of his face. Physical\nexamination shows no abnormality of\ncranial nerves. These physical signs are\nmost likely to be associated with which\none of the following causal conditions?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.091","duplicate_group_id":"exact-13edaee7351f","duplicate_sources":[{"record_id":"fedf00d732da81919131","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":92,"source_qid":"2.091"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"fedf00d732da81919131","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":92,"source_qid":"2.091","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 2 - Trial Examination\nMCQ 2.091\nOver the course of a month, a 75-year-old man has two episodes of blurring of vision\naffecting the right eye. Each lasted around five minutes with gradual complete\nresolution. Ocular examination on Presentation to his general practitioner shows\nnormal eye movements and pupil reactions. Which one of the following is the most\nappropriate next step in investigation?\n. Ocular tonometry.\nCarotid duplex Doppler studies.\n. Cerebral computed tomography (CT).\n. 24-hour BP monitoring.\nTemporal artery biopsy.\n——o————————\nMCQ 2.092\nMESZ@ gr: >\nA 35-year-old mother of an 8-year-old child is considering a second pregnancy.\nHer previous pregnancy was complicated by puerperal psychosis, for which she\nhad electroconvulsive therapy (ECT), and from which she made a prompt recovery\nand has remained well since. Her physical health is excellent and she has a happy\nmarriage. Patient records indicate she is a very good mother. Which one of the\nfollowing is the most appropriate advice?","options":{"A":"In view of her age and previous problem, further pregnancies are out of the\nquestion.","B":"Start another pregnancy and see how she feels about it. If she has misgivings,\nthen have the pregnancy terminated.","C":"In view of her good outcome, there is minimal tisk of further recurrence.","D":"If she gets pregnant, then she should take prophylactic antipsychotics\nthroughout the pregnancy.","E":"There is a 15-20% chance of recurrence of psychosis postpartum.\n\nOO\n\nMCQ 2.093\n\nA 65-year-old man attends his local\ndoctor for a repeat prescription for\nan antihypertensive medication. The\ndoctor notices that the patient''s left\npupil is smaller than the right and is\nassociated with a drooping of the eyelid\nas illustrated. The patient comments\nthat he has noticed recently that even\nwhen he is hot, there is no sweating\non the left side of his face. Physical\nexamination shows no abnormality of\ncranial nerves. These physical signs are\nmost likely to be associated with which\none of the following causal conditions?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","pregnan","therapy"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"13edaee7351f514fd0dbff8cec0f970c1b2f9de1","duplicate_group_id":"exact-13edaee7351f","duplicate_sources":[{"record_id":"fedf00d732da81919131","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":92,"source_qid":"2.091"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
