INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('07aef86dedc89e7cbbe5','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','101','Mixed/Unclassified','Australian Medical Council
Section 2 - Trial Examination
MCQ 2.118
A 54-year-old woman presents with a two-month history of
an intermittent dark discharge from her right nipple. She has
no other breast symptoms. Examination is normal apart from
the production of a small volume of dark brown discharge
from a single duct as illustrated when the area around the
lateral aspect of the nipple is pressed. Microscopy of the
discharge shows haemosiderin-containing macrophages
and red blood cells. Which one of the following is the most
likely diagnosis?
A. Benign duct papilloma.
B. Intraductal carcinoma-in-situ (DCIS).
C. Mammary duct ectasia.
D. Paget disease.
E. Mondor disease.
MCQ 2.119
A 22-year-old woman experiences sudden onset of chest pain on the right side and
shortness of breath. Admission chest imaging shows a significant 20% pneumothorax
on the right side. Which one of the following is the most appropriate treatment of her
condition?','{"A":"Bed rest until the pneumothorax resolves.","B":"Needle aspiration of the right pleural cavity until all air is removed.","C":"Right-sided intercostal tube to underwater seal.","D":"Thoracotomy and suture of the leak.","E":"Bed rest with intermittent positive pressure breathing (IPPB).\nMCQ 2.120"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[101],"source_qid":"2.118","duplicate_group_id":"exact-071cfbc29829","duplicate_sources":[{"record_id":"07aef86dedc89e7cbbe5","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":101,"source_qid":"2.118"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"07aef86dedc89e7cbbe5","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":101,"supporting_pages":[101],"source_qid":"2.118","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 2 - Trial Examination\nMCQ 2.118\nA 54-year-old woman presents with a two-month history of\nan intermittent dark discharge from her right nipple. She has\nno other breast symptoms. Examination is normal apart from\nthe production of a small volume of dark brown discharge\nfrom a single duct as illustrated when the area around the\nlateral aspect of the nipple is pressed. Microscopy of the\ndischarge shows haemosiderin-containing macrophages\nand red blood cells. Which one of the following is the most\nlikely diagnosis?\nA. Benign duct papilloma.\nB. Intraductal carcinoma-in-situ (DCIS).\nC. Mammary duct ectasia.\nD. Paget disease.\nE. Mondor disease.\nMCQ 2.119\nA 22-year-old woman experiences sudden onset of chest pain on the right side and\nshortness of breath. Admission chest imaging shows a significant 20% pneumothorax\non the right side. Which one of the following is the most appropriate treatment of her\ncondition?","options":{"A":"Bed rest until the pneumothorax resolves.","B":"Needle aspiration of the right pleural cavity until all air is removed.","C":"Right-sided intercostal tube to underwater seal.","D":"Thoracotomy and suture of the leak.","E":"Bed rest with intermittent positive pressure breathing (IPPB).\nMCQ 2.120"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"071cfbc298292fd7f7411f5e13897b5e6815ec88","duplicate_group_id":"exact-071cfbc29829","duplicate_sources":[{"record_id":"07aef86dedc89e7cbbe5","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":101,"source_qid":"2.118"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.opt