INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b153a0d81d925c43944f','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','101','Mixed/Unclassified','Australian Medical Council
Section 2 - Trial Examination
MCQ 2.118
A 54-year-old woman presents with a two-month history of
an intermittent dark discharge from her right nipple. She has
no other breast symptoms. Examination is normal apart from
the production of a small volume of dark brown discharge
from a single duct as illustrated when the area around the
lateral aspect of the nipple is pressed. Microscopy of the
discharge shows haemosiderin-containing macrophages
and red blood cells. Which one of the following is the most
likely diagnosis?
A. Benign duct papilloma.
B. Intraductal carcinoma-in-situ (DCIS).
C. Mammary duct ectasia.
D. Paget disease.
E. Mondor disease.
MCQ 2.119
A 22-year-old woman experiences sudden onset of chest pain on the right side and
shortness of breath. Admission chest imaging shows a significant 20% pneumothorax
on the right side. Which one of the following is the most appropriate treatment of her
condition?
A. Bed rest until the pneumothorax resolves.
B. Needle aspiration of the right pleural cavity until all air is removed.
C. Right-sided intercostal tube to underwater seal.
D. Thoracotomy and suture of the leak.
E. Bed rest with intermittent positive pressure breathing (IPPB).
MCQ 2.120
A 4-year-old boy was seen by his general practitioner with an acute otitis media of
his right ear. He has a known allergy to penicillin and was started on erythromycin
suspension four times daily. Four days later he now presents with poor appetite,
central abdominal pain and three to four loose bowel motions per day. On
examination he is afebrile but still distressed, with some nonspecific generalised
abdominal tenderness. There is no rebound tenderness. His otitis is settling well.
Which one of the following is the most appropriate next step in management?','{"A":"Stop his antibiotic treatment.","B":"Arrange an abdominal ultrasound.","C":"Arrange a rotavirus screen of stool.","D":"Ask a surgeon to review him to exclude acute appendicitis.","E":"Check his faeces for giardia.\n85"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[101],"source_qid":"2.118","duplicate_group_id":"exact-07dc3ee153f7","duplicate_sources":[{"record_id":"b153a0d81d925c43944f","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":101,"source_qid":"2.118"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"b153a0d81d925c43944f","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":101,"supporting_pages":[101],"source_qid":"2.118","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 2 - Trial Examination\nMCQ 2.118\nA 54-year-old woman presents with a two-month history of\nan intermittent dark discharge from her right nipple. She has\nno other breast symptoms. Examination is normal apart from\nthe production of a small volume of dark brown discharge\nfrom a single duct as illustrated when the area around the\nlateral aspect of the nipple is pressed. Microscopy of the\ndischarge shows haemosiderin-containing macrophages\nand red blood cells. Which one of the following is the most\nlikely diagnosis?\nA. Benign duct papilloma.\nB. Intraductal car